+package com.example.xpath.service;
+
+import javax.xml.parsers.DocumentBuilder;
+import javax.xml.parsers.DocumentBuilderFactory;
+import javax.xml.xpath.XPath;
+import javax.xml.xpath.XPathFactory;
+import org.w3c.dom.Document;
+
+import java.io.InputStream;
+
+public class UserService {
+
+    private final Document document;
+
+    public UserService() {
+        try {
+            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
+            // Prevent XXE attacks
+            factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
+            factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
+            factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
+
+            DocumentBuilder builder = factory.newDocumentBuilder();
+            InputStream is = getClass().getClassLoader().getResourceAsStream("users.xml");
+            if (is == null) {
+                throw new RuntimeException("users.xml not found on classpath");
+            }
+            document = builder.parse(is);
+        } catch (Exception e) {
+            throw new RuntimeException("Failed to parse users.xml", e);
+        }
+    }
+
+    public String findUserRoleByUsername(String username) {
+        if (username == null || username.isEmpty()) {
+            return null;
+        }
+
+        try {
+            XPath xpath = XPathFactory.newInstance().newXPath();
+            String expression = "//user[name=" + quoteXPathLiteral(username) + "]/role";
+            String role = xpath.evaluate(expression, document);
+            return role.isEmpty() ? null : role;
+        } catch (Exception e) {
+            throw new RuntimeException("Failed to evaluate XPath expression", e);
+        }
+    }
+
+    /**
+     * Safely quotes a string value for use in an XPath 1.0 expression,
+     * preventing XPath injection.
+     */
+    private static String quoteXPathLiteral(String value) {
+        if (!value.contains("'")) {
+            return "'" + value + "'";
+        } else if (!value.contains("\"")) {
+            return "\"" + value + "\"";
+        } else {
+            // Value contains both single and double quotes — use concat()
+            StringBuilder sb = new StringBuilder("concat(");
+            boolean first = true;
+            for (int i = 0; i < value.length(); i++) {
+                char c = value.charAt(i);
+                if (!first) {
+                    sb.append(",");
+                }
+                first = false;
+                if (c == '\'') {
+                    sb.append("\"'\"");
+                } else if (c == '"') {
+                    sb.append("'\"'");
+                } else {
+                    sb.append("'").append(c).append("'");
+                }
+            }
+            sb.append(")");
+            return sb.toString();
+        }
+    }
